use super::geometry::{Path64, Paths64, Point64};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum JoinType {
    Square,
    Round,
    Miter,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EndType {
    Polygon,
    Joined,
    Butt,
    Square,
    Round,
}

pub fn inflate_paths(
    paths: &Paths64,
    delta: f64,
    join_type: JoinType,
    end_type: EndType,
) -> Paths64 {
    if !delta.is_finite() {
        return Vec::new();
    }

    match (join_type, end_type) {
        (JoinType::Square, EndType::Polygon) => {
            paths.iter().map(|path| inflate_polygon_bbox(path, delta)).collect()
        }
        _ => paths.clone(),
    }
}

fn inflate_polygon_bbox(path: &Path64, delta: f64) -> Path64 {
    if path.is_empty() {
        return Vec::new();
    }

    let mut min_x = path[0].x;
    let mut min_y = path[0].y;
    let mut max_x = path[0].x;
    let mut max_y = path[0].y;

    for point in &path[1..] {
        min_x = min_x.min(point.x);
        min_y = min_y.min(point.y);
        max_x = max_x.max(point.x);
        max_y = max_y.max(point.y);
    }

    let delta = delta.round() as i64;

    vec![
        Point64::new(min_x - delta, min_y - delta),
        Point64::new(max_x + delta, min_y - delta),
        Point64::new(max_x + delta, max_y + delta),
        Point64::new(min_x - delta, max_y + delta),
    ]
}

#[cfg(test)]
mod tests {
    use super::{inflate_paths, EndType, JoinType};
    use crate::clipper2::{Path64, Paths64, Point64};

    #[test]
    fn square_polygon_offset_keeps_single_path() {
        let path: Path64 = vec![
            Point64::new(0, 0),
            Point64::new(100, 0),
            Point64::new(100, 100),
            Point64::new(0, 100),
        ];
        let paths: Paths64 = vec![path];

        let result = inflate_paths(&paths, 10.0, JoinType::Square, EndType::Polygon);

        assert_eq!(result.len(), 1);
        assert_eq!(
            result[0],
            vec![
                Point64::new(-10, -10),
                Point64::new(110, -10),
                Point64::new(110, 110),
                Point64::new(-10, 110),
            ]
        );
    }
}

